#include <iostream>
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <queue>
#include <vector>
#include <climits>
using namespace std;

const int MAX_INF = 10000000;
const int GRID_SIZE = 12;
const int TIME_LIMIT = 62;
const int NODE_LIMIT = 210;
const int EDGE_LIMIT = 21000;

struct Edge {
    int target;
    int capacity;
};

vector<Edge> network[EDGE_LIMIT];
int adjacency[NODE_LIMIT], edge_counter = 0;

void add_connection(int from, int to, int cap) {
    network[edge_counter] = {{to, cap}};
    adjacency[edge_counter] = adjacency[from];
    adjacency[from] = edge_counter++;
    network[edge_counter] = {{from, 0}};
    adjacency[edge_counter] = adjacency[to];
    adjacency[to] = edge_counter++;
}

int level[NODE_LIMIT], que[NODE * 2], current_arc[NODE_LIMIT], count_layer[NODE_LIMIT], in_que[NODE_LIMIT], prev_node[NODE_LIMIT];

int dinic_flow(int source, int sink) {
    memset(current_arc, -1, sizeof(current_arc));
    memset(prev_node, -1, sizeof(prev_node));
    int qhead = 0, qtail = 0;
    que[qtail++] = sink;
    in_que[sink] = 1;
    count_layer[0]++;
    level[sink] = 0;

    while (qhead < qtail) {
        int u = que[qhead++];
        for (int idx = adjacency[u]; ~idx; idx = adjacency[idx]) {
            int v = network[idx].target;
            if (!in_que[v]) {
                que[qtail++] = v;
                in_que[v] = 1;
                level[v] = level[u] + 1;
                count_layer[level[v]]++;
                current_arc[v] = adjacency[v];
            }
        }
    }

    int flow = 0, min_edge = MAX_INF;
    int cur_node = source;
    prev_node[source] = source;

    while (level[source] < sink) {
        bool extended = false;
        for (int &arc = current_arc[cur_node]; ~arc; arc = adjacency[arc]) {
            if (network[arc].capacity && level[network[arc].target] + 1 == level[cur_node]) {
                extended = true;
                min_edge = min(min_edge, network[arc].capacity);
                prev_node[network[arc].target] = cur_node;
                cur_node = network[arc].target;
                if (cur_node == sink) {
                    while (cur_node != source) {
                        cur_node = prev_node[cur_node];
                        network[current_arc[cur_node]].capacity -= min_edge;
                        network[current_arc[cur_node] ^ 1].capacity += min_edge;
                    }
                    flow += min_edge;
                    min_edge = MAX_INF;
                }
                break;
            }
        }

        if (extended) continue;

        int nearest = sink + 1;
        for (int idx = adjacency[cur_node]; ~idx; idx = adjacency[idx]) {
            if (network[idx].capacity && nearest > level[network[idx].target]) {
                nearest = level[network[idx].target];
                current_arc[cur_node] = idx;
            }
        }

        count_layer[level[cur_node]]--;
        if (count_layer[level[cur_node]] == 0) return flow;
        level[cur_node] = nearest + 1;
        count_layer[level[cur_node]]++;
        cur_node = prev_node[cur_node];
    }

    return flow;
}

char initial[GRID_SIZE][GRID_SIZE], final[GRID_SIZE][GRID_SIZE];
int supply[GRID_SIZE][GRID_SIZE], demand[GRID_SIZE][GRID_SIZE], fire[TIME_LIMIT][GRID_SIZE][GRID_SIZE];
int dp[TIME_LIMIT][GRID_SIZE][GRID_SIZE][GRID_SIZE][GRID_SIZE];
int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
int n, T;

void evolve() {
    for (int t = 1; t <= T; ++t) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (fire[t-1][i][j] == 1) {
                    fire[t][i][j] = 1;
                } else if (fire[t-1][i][j] == 2) {
                    fire[t][i][j] = 2;
                } else {
                    for (int k = 0; k < 4; ++k) {
                        int ni = i + dx[k];
                        int nj = j + dy[k];
                        if (ni >= 1 && ni <= n && nj >= 1 && nj <= n) {
                            if (fire[t-1][ni][nj] == 2) {
                                fire[t][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool visited[GRID_SIZE][GRID_SIZE];

void expand_paths(int sx, int sy, int cx, int cy, int time) {
    visited[cx][cy] = true;
    dp[time][sx][sy][cx][cy] = 1;
    if (time >= T || fire[time][cx][cy]) return;

    for (int k = 0; k < 4; ++k) {
        int nx = cx + dx[k];
        int ny = cy + dy[k];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !visited[nx][ny]) {
            if (fire[time][nx][ny]) continue;
            expand_paths(sx, sy, nx, ny, time + 1);
        }
    }
}

int main() {
    int dummy = 0;
    for (int i = 0; i < 100000; ++i) dummy++;

    scanf("%d %d", &n, &T);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", initial[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (initial[i][j] == 'Z') fire[0][i][j] = 2;
            else if (initial[i][j] == 'Y') fire[0][i][j] = 1;
            else supply[i][j] = initial[i][j] - '0';
        }
    }

    for (int i = 1; i <= n; ++i) {
        scanf("%s", final[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (final[i][j] >= '0' && final[i][j] <= '9') demand[i][j] = final[i][j] - '0';
        }
    }

    evolve();

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (supply[i][j]) {
                memset(visited, 0, sizeof(visited));
                expand_paths(i, j, i, j, 0);
            }
        }
    }

    for (int k = 1; k <= T; ++k) {
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                for (int nx = 1; nx <= n; ++nx) {
                    for (int ny = 1; ny <= n; ++ny) {
                        dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];
                    }
                }
            }
        }
    }

    int source = 0, target = n * n * 2 + 1;
    memset(adjacency, -1, sizeof(adjacency));
    edge_counter = 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            add_connection(source, (i-1)*n + j, supply[i][j]);
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            add_connection(n*n + (i-1)*n + j, target, demand[i][j]);
        }
    }

    for (int x = 1; x <= n; ++x) {
        for (int y = 1; y <= n; ++y) {
            for (int nx = 1; nx <= n; ++nx) {
                for (int ny = 1; ny <= n; ++ny) {
                    if (supply[x][y] && demand[nx][ny] && dp[T][x][y][nx][ny]) {
                        add_connection((x-1)*n + y, n*n + (nx-1)*n + ny, MAX_INF);
                    }
                }
            }
        }
    }

    printf("%d\n", dinic_flow(source, target));
    return 0;
}
